• فارسی خیلی ساده: تقطیع یعنی شعر را به هجاها ببری و هجاها را بشماری
• شکل: بیت را مثل یک نان سنگک ببین که تکه‌تکه‌اش می‌کنی؛ هر تکه یک هجاست
• ریتم و صدا: «بخوان، بزن، بنویس، علامت بزن!»

