• حالا با دست بزن و بگو: «تَک، تَن، تَن، تَن | تَک، تَن، تَن، تَن | تَک، تَن، تَن، تَن | تَک، تَن، تَن، تَن». «تَک» یعنی یک ضربه کوتاه و تند (هجای کوتاه) و «تَن» یعنی یک ضربه بلند و کش‌دار (هجای بلند). این چهار تکه را چهار بار بزن؛ یعنی ۱۶ ضربه داری.
