• چرا به آن «هزج» می‌گویند؟ چون «هزج» در عربی یعنی آواز خوش و آهنگین؛ این آهنگ هم مثل یک آواز آرام و خوش‌آهنگ است که حافظ خیلی دوستش داشت.

🎵 چهار کانال یادگیری این درس:
• هزج = ترکی «آهنگ» (همان آهنگ) | فارسی ساده: یک قدم کوتاه، سه قدم بلند، چهار بار | شکل: چهار تکه «تَک، تَن، تَن، تَن» پشت سر هم | ریتم: «تَک، تَن، تَن، تَن!»
• مفاعیلن = ترکی «بیر پارچا آهنگ» (یک تکه آهنگ) | فارسی ساده: همان یک تکه که چهار بار تکرار می‌شود | شکل: یک رکن با الگوی کوتاه و سه بلند | ریتم: «تَک، تَن، تَن، تَن!»
• بحر = ترکی «دنیز» (دریا) | فارسی ساده: خانواده همه شعرهایی که یک آهنگ دارند | شکل: یک دریا که همه بیت‌های هم‌آهنگ در آن‌اند | ریتم: «یک دریا، یک آهنگ!»

