🎵 چهار کانال یادگیری این درس:
• رمل = ترکی «آهنگ» (همان آهنگ) | فارسی ساده: یک بلند، یک کوتاه، دو بلند | شکل: تکه‌های «تَن، تَک، تَن، تَن» پشت سر هم | ریتم: «تَن، تَک، تَن، تَن!»
• فاعلاتن = ترکی «بیر پارچا آهنگ» (یک تکه آهنگ) | فارسی ساده: همان یک تکه که تکرار می‌شود | شکل: یک رکن با الگوی یک بلند، یک کوتاه، دو بلند | ریتم: «تَن، تَک، تَن، تَن!»
• نی = ترکی «قامیش» (نی) | فارسی ساده: نیِ مولوی که شکایت می‌کند | شکل: نی که صدایش آهنگ دارد | ریتم: «بشنو این نی!»

