🎵 چهار کانال یادگیری این درس:
• مضارع = ترکی «آهنگ» (همان آهنگ) | فارسی ساده: دو بلند، یک کوتاه، یک بلند، یک کوتاه، دو بلند | شکل: دو نیمه «تَن، تَن، تَک، تَن، تَک، تَن، تَن» | ریتم: «تَن، تَن، تَک، تَن، تَک، تَن، تَن!»
• مفعول فاعلاتن = ترکی «ایکی پارچا آهنگ» (دو تکه آهنگ) | فارسی ساده: دو تکه که با هم یک نیمه می‌سازند | شکل: «مفعول» سه ضربه و «فاعلاتن» چهار ضربه | ریتم: «تَن، تَن، تَک، تَن، تَک، تَن، تَن!»
• مکث = ترکی «دایانماق» (ایستادن) | فارسی ساده: استراحت کوتاه وسط مصراع | شکل: علامت مکث وسط مصراع | ریتم: «بخوان، بایست، بخوان!»

