🎵 چهار کانال یادگیری این درس:
• مجتث = ترکی «آهنگ» (همان آهنگ) | فارسی ساده: کوتاه، بلند، کوتاه، بلند، بعد دو کوتاه و دو بلند | شکل: تکه‌های «تَک، تَن، تَک، تَن» و «تَک، تَک، تَن، تَن» یکی‌درمیان | ریتم: «تَک، تَن، تَک، تَن، تَک، تَک، تَن، تَن!»
• مفاعلن فعلاتن = ترکی «ایکی پارچا آهنگ» (دو تکه آهنگ) | فارسی ساده: دو تکه که یکی‌درمیان تکرار می‌شوند | شکل: «مفاعلن» چهار ضربه و «فعلاتن» چهار ضربه | ریتم: «تَک، تَن، تَک، تَن، تَک، تَک، تَن، تَن!»
• غزل = ترکی «غزل» (همان غزل) | فارسی ساده: شعری که با این آهنگ زیاد سروده می‌شود | شکل: غزل‌های سعدی و حافظ | ریتم: «مجتث، پرکاربردترین وزن غزل!»

