🎵 چهار کانال یادگیری این درس:
• متقارب = ترکی «آهنگ» (همان آهنگ) | فارسی ساده: یک کوتاه، دو بلند، چهار بار | شکل: تکه‌های سه ضربه‌ای «تَک، تَن، تَن» پشت سر هم | ریتم: «تَک، تَن، تَن!»
• فعولن = ترکی «بیر پارچا آهنگ» (یک تکه آهنگ) | فارسی ساده: همان یک تکه سه ضربه‌ای که تکرار می‌شود | شکل: یک رکن با الگوی یک کوتاه و دو بلند | ریتم: «تَک، تَن، تَن!»
• شاهنامه = ترکی «شاهنامه» (همان شاهنامه) | فارسی ساده: کتاب فردوسی که با همین آهنگ سروده شده است | شکل: شاهنامه با آهنگ طبل جنگ | ریتم: «تَک، تَن، تَن!»

