🎵 چهار کانال یادگیری این درس:
• کامل = ترکی «آهنگ» (همان آهنگ) | فارسی ساده: دو کوتاه، یک بلند، یک کوتاه، یک بلند، چهار بار | شکل: چهار تکه «تَک، تَک، تَن، تَک، تَن» پشت سر هم | ریتم: «تَک، تَک، تَن، تَک، تَن!»
