• نامشخص = ترکی «بیلینمه‌ین» (ناشناخته) | فارسی ساده: بیت معروفش در جدول ۱۶ وزن نیامده است | شکل: جای بیت خالی است تا چیزی حدس زده نشود | ریتم: «اول آهنگ، بعد بیت!»

