• مفتعلن فاعلات = ترکی «ایکی پارچا آهنگ» (دو تکه آهنگ) | فارسی ساده: دو تکه که با هم می‌آیند و تکرار می‌شوند | شکل: «مفتعلن» چهار ضربه و «فاعلات» سه ضربه | ریتم: «تَن، تَک، تَک، تَن، تَک، تَن!»
• ناهمسان = ترکی «فرقلی» (متفاوت) | فارسی ساده: رکن‌های مصراع یکی نیستند | شکل: تکه‌هایی با ضربه‌های مختلف | ریتم: «یکی نیستند!»

