🎵 چهار کانال یادگیری این درس:
• اختیار = ترکی «اختیار» (اجازه شاعر) | فارسی ساده: اجازه عوض کردن وزن، نه تقلب | شکل: جدول دو دسته زبانی و وزنی | ریتم: «حذف، بلند، ادغام!»
• حذف همزه = ترکی «همزه‌نی سیلمک» (پاک کردن همزه) | فارسی ساده: همزه خوانده نمی‌شود | شکل: «دستِ او» به «دَس + تو» | ریتم: «حذف کن، وصل کن!»
• تسکین = ترکی «ساکیت‌لش‌دیرمک» (آرام کردن) | فارسی ساده: دو کوتاه به یک بلند | شکل: دو تا U به یک – | ریتم: «دو تا، یکی شد!»

