• حالا هر اختیار را یکی‌یکی با مثال یاد می‌گیریم. اول گوش بده، بعد با دست ضرب بگیر، بعد مثال را تقطیع کن.
• اختیار اول، حذف همزه (زبانی): اگر بعد از صامت، همزه (الف آغازی) بیاید، همزه تلفظ نمی‌شود و صامت قبلی به مصوت بعدی وصل می‌شود. مثال شنیداری: «دستِ او» ⟹ «دَس + تو»؛ همزه «او» حذف شد و «ت» به مصوت بلند «او» وصل شد. نشانه‌اش چیست؟ وقتی کلمه‌ای با «ا» شروع می‌شود و قبلش صامت است، همزه‌اش را نخوان.
• اختیار دوم، حذف نون بعد از مصوت بلند (زبانی): در کلمات «جان، نان، خون، دین، چون، آن، این» اگر در وسط مصراع بیایند و وزن نیاز داشته باشد، «ن» تلفظ نمی‌شود و کلمه به جای کشیده (– U)، بلند (–) حساب می‌شود. مثال شنیداری: «بشنو این نی چون شکایت می‌کند» ⟹ «چون» را «چو» بخوان؛ وگرنه مصراع ۱۲ موضع می‌شود، نه ۱۱. مثال دوم: «دل می‌رود ز دستم صاحبدلان خدا را» ⟹ «صاحبدلان» را «صاحبدلا» بخوان؛ وگرنه نیمه دوم یک هجا اضافه می‌آورد.
• اختیار سوم، تغییر کمیت مصوت‌ها (زبانی): بلند تلفظ کردن مصوت کوتاه (مثلاً کسره اضافه «ِ» یا «و» عطف را بلند می‌خوانیم) یا کوتاه تلفظ کردن مصوت بلند (در کلمات «سو، رو، مو» قبل از مصوت، مصوت بلند را کوتاه می‌خوانیم). نشانه‌اش چیست؟ وقتی هجایی باید بلند باشد ولی مصوتش کوتاه است، شاعر آن را بلند خوانده است؛ و برعکس.
• اختیار چهارم، تسکین (وزنی): تبدیل کردن دو هجای کوتاه پیاپی (U U) به یک هجای بلند (–)! یعنی شاعر دو کوتاه را یکی می‌کند تا در وزن جا شود. نشانه‌اش چیست؟ وقتی دو هجای کوتاه پیاپی داری و وزن یک بلند می‌خواهد، تسکین است.
• اختیار پنجم، آوردن «فاعلاتن» به جای «فعلاتن» فقط در رکن اول مصراع (وزنی): شاعر فقط در رکن اول می‌تواند «فاعلاتن» را به جای «فعلاتن» بیاورد؛ در رکن‌های بعدی نه. نشانه‌اش چیست؟ اگر رکن اول «فاعلاتن» بود و بقیه «فعلاتن»، این اختیار است؛ اگر رکن دوم هم «فاعلاتن» بود، دیگر اختیار نیست، وزن عوض شده است.
• اختیار ششم، قلب (زبانی): جای مصوت و صامت در یک هجا عوض می‌شود؛ این اختیار در کنکور کم می‌آید و معمولاً با تقطیع مشخص می‌شود، نه با حفظ مثال؛ پس اگر در تستی دیدی که هیچ‌یک از اختیارهای بالا نیست، به قلب فکر کن. منبع: کتاب علوم و فنون ادبی ۳ + گنجور برای بیت‌ها.

📖 آموزش کامل و پله‌به‌پله مفاهیم این گام:
• حذف همزه: بعد از صامت، همزه تلفظ نمی‌شود؛ «دستِ او» ⟹ «دَس + تو».
• حذف نون: «چون» ⟹ «چو» و «صاحبدلان» ⟹ «صاحبدلا»؛ نون بعد از مصوت بلند خوانده نمی‌شود.
• تغییر کمیت مصوت‌ها: بلند خواندن مصوت کوتاه (کسره اضافه، «و» عطف) یا کوتاه خواندن مصوت بلند («سو، رو، مو» قبل از مصوت).
• تسکین: دو هجای کوتاه پیاپی (U U) به یک هجای بلند (–) تبدیل می‌شوند.
• فاعلاتن به جای فعلاتن: فقط در رکن اول مصراع مجاز است؛ در رکن‌های بعدی نه.
• قلب: جابه‌جا شدن جای مصوت و صامت در یک هجا؛ در کنکور کم می‌آید و با تقطیع مشخص می‌شود.""",
