حذف نون → در کلمات جان و نان و خون و دین و چون و آن و این، اگر در وسط مصراع بیایند و وزن نیاز داشته باشد، نون تلفظ نمی‌شود؛ چون به چو تبدیل می‌شود
تغییر کمیت مصوت‌ها → بلند خواندن مصوت کوتاه مثل کسره اضافه و واو عطف، یا کوتاه خواندن مصوت بلند در کلمات سو و رو و مو قبل از مصوت
