• تا اینجا شش اختیار را با مثال شنیداری یاد گرفتی. اما سوال اصلی اینه: «چه اشتباه‌هایی تشخیص اختیار را خراب می‌کند و اختیار با اشتباه تقطیع چه فرقی دارد؟»
• اشتباه اول: فکر کردن اینکه تقطیع اشتباه است. خیلی‌ها وقتی علامت‌ها جور درنمی‌آیند، فکر می‌کنند تقطیعشان اشتباه است و از اول شروع می‌کنند؛ در حالی که شاعر اختیار به کار برده است. درمان: اول بپرس «کدام اختیار است؟»؛ اگر یکی از شش اختیار بود، تقطیع‌ات درست است.
• اشتباه دوم: اختیار را همه‌جا دیدن. خیلی‌ها هر جا علامت‌ها جور نشد، می‌گویند «اختیار است»؛ در حالی که گاهی واقعاً تقطیع اشتباه است. درمان: اول تقطیع را چک کن (مرحله ۱ تا ۴ را دوباره انجام بده)؛ اگر هنوز جور نشد، بعد سراغ اختیار برو.
• اشتباه سوم: فاعلاتن به جای فعلاتن در رکن دوم. خیلی‌ها فکر می‌کنند این اختیار در همه رکن‌ها مجاز است؛ ولی فقط در رکن اول مجاز است. درمان: رکن اول را چک کن؛ اگر رکن دوم هم «فاعلاتن» بود، وزن عوض شده است، نه اختیار.
• اشتباه چهارم: تسکین را با حذف اشتباه گرفتن. تسکین یعنی دو کوتاه به یک بلند تبدیل می‌شوند؛ حذف یعنی یک حرف خوانده نمی‌شود. درمان: اگر دو هجای کوتاه داری که یکی شدند، تسکین است؛ اگر یک حرف نیست، حذف است.
• مرز اختیار با اشتباه تقطیع: اگر با یکی از شش اختیار، علامت‌ها با وزن جور درمی‌آیند، اختیار است؛ اگر با هیچ اختیاری جور درنیامدند، تقطیع‌ات اشتباه است و باید از مرحله ۱ دوباره شروع کنی.
