🎵 چهار کانال یادگیری این درس:
• قافیه = ترکی «آخیر سؤزلر عینی‌دیر» (کلمه‌های آخر یکی‌اند) | فارسی ساده: صدای یکیِ آخر دو مصراع | شکل: دو مصراع با کلمه‌های قافیه رنگی | ریتم: «آخر، آخر، یکی!»
• ردیف = ترکی «تکرار اولان سؤز» (کلمه تکراری) | فارسی ساده: کلمه عیناً تکراری آخر مصراع | شکل: کلمه تکراری را خط بزن | ریتم: «تکراری را بنداز دور!»
• صدای یکی = ترکی «عینی سس» (صدای یکی) | فارسی ساده: آخر دو مصراع مثل هم شنیده می‌شود | شکل: دو کلمه با پایان رنگی یکی | ریتم: «بشنو، بشنو، یکی!»

