🎵 چهار کانال یادگیری این درس:
• عیب = ترکی «خراب» (خراب بودن) | فارسی ساده: قافیه خراب است و گوش را اذیت می‌کند | شکل: دو کلمه با پایان رنگی متفاوت | ریتم: «جور است، جور نیست!»
• درست = ترکی «دوز» (درست) | فارسی ساده: صدای آخر دو کلمه یکی است | شکل: دو کلمه با پایان رنگی یکی | ریتم: «یکی، یکی، درست!»
• تبصره = ترکی «ایستثنا» (استثنا) | فارسی ساده: قافیه درست ولی قاعده‌اش عجیب است | شکل: قافیه درست با علامت تبصره | ریتم: «درستِ عجیب، تبصره!»

📖 آموزش کامل و پله‌به‌پله مفاهیم این گام:
• عیب قافیه یعنی خرابی در حروف قافیه؛ یعنی دو کلمه‌ای که باید صدای آخرشان یکی باشد، در یک حرف با هم فرق می‌کنند.
