• عیب دوم، اقواء را با گوش بگیر: «پیر» و «دور» را بلند بگو. هر دو به «ـیر» و «ـور» ختم می‌شوند؛ صامت آخر «ر» یکی است ولی مصوت قبلش فرق می‌کند: «ای» و «او». به این می‌گویند اقواء: اختلاف در مصوت قبل از صامت. «اقواء» یعنی «مصوت‌ها با هم نمی‌خوانند».
