🎵 چهار کانال یادگیری این درس:
• اکفاء = ترکی «صامیت فرق ائدیر» (صامت فرق می‌کند) | فارسی ساده: صامت قافیه یکی نیست | شکل: صامت آخر دو کلمه رنگی متفاوت | ریتم: «صامت، صامت، اکفاء!»
• اقواء = ترکی «سس فرق ائدیر» (مصوت فرق می‌کند) | فارسی ساده: مصوت قبل از صامت یکی نیست | شکل: مصوت قبل از صامت رنگی متفاوت | ریتم: «مصوت، مصوت، اقواء!»
• سناد = ترکی «ردفدن قاباقکی سس فرق ائدیر» | فارسی ساده: مصوت قبل از ردف یکی نیست | شکل: مصوت قبل از ردف رنگی | ریتم: «ردف، ردف، سناد!»
• ایطاء = ترکی «یالنیز شکیلچی تکرار اولوب» | فارسی ساده: فقط پسوند تکرار شده است | شکل: پسوند رنگی، بقیه کلمه بی‌رنگ | ریتم: «پسوند، پسوند، ایطاء!»

📖 آموزش کامل و پله‌به‌پله مفاهیم این گام:
• عیب اکفاء: اختلاف در صامت قافیه (سنگ و گنج؛ صامت قافیه یکی نیست).
• عیب اقواء: اختلاف در مصوت قبل از صامت (پیر و دور؛ مصوت قبل از صامت یکی نیست).
• عیب سناد: اختلاف در مصوت قبل از ردف؛ ردف یعنی مصوت بلند (آ، ای، او) که پیش از روی می‌آید (مثل «آ» در «یار» و «کار»)؛ اگر مصوت قبل از ردف فرق کند، سناد است.
• عیب ایطاء (قافیه شایگان): تکرار پسوندها مثل ـان یا ـمند به عنوان کل قافیه (خردمند و هنرمند؛ فقط پسوند «ـمند» تکرار شده و قافیه واقعی ندارند).
