• اشتباه اول: اکفاء را با اقواء اشتباه گرفتن. اکفاء اختلاف در صامت قافیه است (سنگ/گنج)؛ اقواء اختلاف در مصوت قبل از صامت است (پیر/دور). درمان: بپرس «کدام حرف فرق کرده است؟»؛ اگر صامت فرق کرده، اکفاء است؛ اگر مصوت فرق کرده، اقواء است.
• اشتباه دوم: ایطاء را قافیه درست دانستن. خیلی‌ها «خردمند» و «هنرمند» را قافیه درست می‌دانند؛ در حالی که فقط پسوند «ـمند» تکرار شده و قافیه واقعی ندارند. درمان: اگر فقط پسوند تکرار شده بود، ایطاء است؛ بقیه کلمه را هم چک کن.
• اشتباه سوم: سناد را با اقواء اشتباه گرفتن. اقواء یعنی مصوتِ قبل از صامت فرق کرده است؛ سناد یعنی مصوتِ قبل از ردف فرق کرده است. درمان: اول ردف را پیدا کن (مصوت بلند قبل از روی)؛ اگر مصوت قبل از ردف فرق کرده بود، سناد است؛ اگر مصوت قبل از صامتِ آخر فرق کرده بود، اقواء است.
• اشتباه چهارم: عیب را با تبصره اشتباه گرفتن. خیلی‌ها هر قافیه عجیبی را عیب می‌دانند؛ در حالی که تبصره، قافیه درستِ عجیب است و عیب، قافیه خراب است. درمان: اول بپرس «قافیه درست است یا خراب؟»؛ اگر درست ولی عجیب بود، تبصره است؛ اگر خراب بود، عیب است.
• مرز عیب‌ها با هم: صامت فرق کرد؟ اکفاء. مصوت قبل از صامت فرق کرد؟ اقواء. مصوت قبل از ردف فرق کرد؟ سناد. فقط پسوند تکرار شد؟ ایطاء.
• با این دسته‌بندی ذهنی، هم عیب‌ها را از هم جدا می‌کنی و هم سر جلسه، بین گزینه‌ها شک نمی‌کنی.""",
